// NPCの写真素材と設定（ユーザー提供）。
// 2026-11-09 統合レビュー版（drive-download-20261103T030503Z-1-001/統合レビュー_20261109、男性506枚・女性354枚）に置き換え。
// id は p＋manifest の index。年齢・容姿レベル・性別はユーザーがチェックツールで確認した値のまま。趣味は設定のまま。
// 学歴・職業・年収は首都圏のアプリらしい分布に引き直した（男性：写りが冴えない写真ほど高卒・ブルーカラー寄り、容姿4〜5は上位職も多め。医師・弁護士・年収1000万円以上も含む）。
// 元のファイル名から、TikTok風・強い加工は「加工写真」、ジブリ風AIはイラスト、ほかの判定不可は顔出しなし。
// 以前の版の画像（m・k・f で始まるファイル）は 2026-11-15 に指示で削除した（2026-11-09 より前のセーブでは写真が出ない）。s・一部の k は今も使う。
import type { Looks, UniversityGroup } from '../types';
import { ADDED_FEMALE_PHOTOS, ADDED_MALE_PHOTOS } from './npcPhotosAdded';
import { BLURRED_FEMALE_PHOTOS, BLURRED_MALE_PHOTOS } from './npcPhotosBlurred';

export type PhotoEducation = 'top' | 'grad' | 'univ' | 'student' | 'kosen' | 'junior' | 'vocational' | 'highschool';

export interface PhotoTemplate {
  id: string;
  file: string;
  /** 設定の年齢（「◯歳前後」）。NPCの年齢が±3以内なら使う */
  age: number;
  /** 顔評価。顔出しなしの写真は実際の評価 */
  looks: Looks;
  /** 顔が写っているか（後ろ姿・スタンプで隠した写真は false） */
  faceVisible: boolean;
  job?: string;
  /** 年収の幅（万円） */
  income?: [number, number];
  education?: PhotoEducation;
  /** 大学群を決めておく（早慶・MARCHなど。指定がなければ年収から選ぶ。2026-11-14） */
  eduGroup?: UniversityGroup;
  /** 専門の表記（「専門学校在学中」など） */
  eduLabel?: string;
  /** 医師・弁護士を偽る人にしない（見た目に合わせて職業を決めた素材。2026-11-14） */
  noFakeTitle?: boolean;
  hobbies?: string[];
  /** 写真のウケが悪い（トイレ自撮り・顔が隠れている・結婚相談所風・画質が悪い）＝人気が下がる */
  weakPhoto?: boolean;
  livesWithParents?: boolean;
  /** 身長の設定（「低め」「高め」） */
  height?: 'short' | 'tall';
  /** 身長の設定値（cm） */
  heightCm?: number;
  /** TikTok風の加工写真（実物は写真より容姿が下。ヤリ目・ドタキャン・別人が多い） */
  filtered?: boolean;
  /** ジブリ風などのAIイラスト（顔出しなし扱い） */
  illustration?: boolean;
  /** 高級料理店・アフタヌーンティー・ホテルの写真（女性：メシ目がやや多い） */
  luxury?: boolean;
  /** 夜職フォルダの素材：normal＝ふつうの人、bar＝メシ目＋ぼったくりバーへ勧誘、meshi＝高めの店を提案し交際にはならない */
  nightWork?: 'normal' | 'bar' | 'meshi';
  /** 設定メモ（開発用） */
  note: string;
}

